mod solution;

fn main() {
    let cases = [
    (r#"edges=0-1:0,0-2:1,1-2:0,2-3:1"#, r#"1"#),
    (r#"edges=0-1:1,1-3:1"#, r#"2"#),
    (r#"
edges=0-1:1,1-3:1
"#, r#"2"#),
    (r#"  
edges=0-1:0,0-2:1,1-2:0,2-3:1
  "#, r#"1"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS zero-one-bfs");
}
